.darma-loader-darma-b15-wine-swirl { --accent: var(--loader-color, #9f1239); --accent-2: var(--loader-secondary-color, #fb7185); width: var(--loader-size, 106px); height: var(--loader-size, 106px); position: relative; }
.darma-loader-darma-b15-wine-swirl .darma-loader-darma-b15-wine-swirl__bowl { position: absolute; left: 24%; top: 6%; width: 52%; height: 48%; border-radius: 8% 8% 46% 46% / 6% 6% 62% 62%; overflow: hidden; background: color-mix(in srgb, var(--accent-2) 18%, transparent); box-shadow: inset 0 0 0 2px color-mix(in srgb, var(--accent-2) 45%, transparent); animation: darma-loader-darma-b15-wine-swirl-wine-tip calc(var(--loader-speed, 1s) * 2) ease-in-out infinite; }
.darma-loader-darma-b15-wine-swirl .darma-loader-darma-b15-wine-swirl__wine { position: absolute; left: -20%; right: -20%; bottom: -10%; height: 66%; border-radius: 44% 44% 0 0 / 30% 30% 0 0; background: linear-gradient(var(--accent), color-mix(in srgb, #000 22%, var(--accent))); animation: darma-loader-darma-b15-wine-swirl-wine-slosh calc(var(--loader-speed, 1s) * 2) ease-in-out infinite; }
.darma-loader-darma-b15-wine-swirl .darma-loader-darma-b15-wine-swirl__stem { position: absolute; left: 47%; top: 54%; width: 6%; height: 30%; background: color-mix(in srgb, var(--accent-2) 45%, transparent); }
.darma-loader-darma-b15-wine-swirl .darma-loader-darma-b15-wine-swirl__foot { position: absolute; left: 28%; right: 28%; bottom: 8%; height: 8%; border-radius: 50%; background: color-mix(in srgb, var(--accent-2) 45%, transparent); }
@keyframes darma-loader-darma-b15-wine-swirl-wine-tip { 0%, 100% { transform: rotate(-8deg); } 50% { transform: rotate(8deg); } }
@keyframes darma-loader-darma-b15-wine-swirl-wine-slosh { 0%, 100% { transform: rotate(9deg) translateX(-4%); } 50% { transform: rotate(-9deg) translateX(4%); } }

